package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import org.json.*;import java.io.*;import app.layan.quran.*;
public final class FontRenderingProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();QiraatData.directory(c).mkdirs();android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",false).putBoolean("useArabicNames",true).commit();StringBuilder records=new StringBuilder();File dir=c.getExternalFilesDir("tests");dir.mkdirs();
 for(String id:new String[]{"hafs","warsh","ibn-wardan","ruways","idris"}){JSONObject m=QiraatData.metadata(c,id);if(!QiraatData.downloaded(c,id)){String url=m.getString("url");File archive=new File("/data/local/tmp/qiraat-corpus",url.substring(url.lastIndexOf('/')+1));QiraatDownload.install(archive,QiraatData.directory(c),id,m.getLong("bytes"),m.getString("sha256"),(p,s)->{});}
 try(QiraatData.Book book=new QiraatData.Book(c,id)){Bitmap b=book.render(300,720);try(FileOutputStream o=new FileOutputStream(new File(dir,"font-"+id+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,o);}b.recycle();}
 QiraatReaderActivity a=(QiraatReaderActivity)startActivitySync(new Intent(c,QiraatReaderActivity.class).putExtra("riwayah",id).putExtra("page",300).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long end=SystemClock.elapsedRealtime()+120000;while(SystemClock.elapsedRealtime()<end){boolean[] ready={false};runOnMainSync(()->ready[0]=a.currentPageReady());if(ready[0])break;SystemClock.sleep(100);}waitForIdleSync();runOnMainSync(()->{View root=a.getWindow().getDecorView();app.layan.quran.view.HighlightingImageView v=find(root);float[] matrix=new float[9];v.getImageMatrix().getValues(matrix);records.append(id+" viewport="+v.getWidth()+"x"+v.getHeight()+" scale="+matrix[0]+","+matrix[4]+" type="+v.getScaleType()+"\n");});Bitmap shot=NativeScreens.capture(this,a);try(FileOutputStream o=new FileOutputStream(new File(dir,"font-page-"+id+".png"))){shot.compress(Bitmap.CompressFormat.PNG,100,o);}shot.recycle();runOnMainSync(a::finish);waitForIdleSync();}
 result.putString("result","PASS\n"+records);finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
 private app.layan.quran.view.HighlightingImageView find(View v){if(v instanceof app.layan.quran.view.HighlightingImageView){Rect r=new Rect();if(v.getGlobalVisibleRect(r)&&r.width()>v.getWidth()/2)return(app.layan.quran.view.HighlightingImageView)v;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){app.layan.quran.view.HighlightingImageView r=find(((ViewGroup)v).getChildAt(i));if(r!=null)return r;}return null;}
}